    private static SearchIntentSuggestion[] SearchV67Direct(string clean, ServiceTarget[] targets, int limit)
    {
        var tokens = clean.Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);

        var hits = ExtendedRows.Select(row =>
        {
            var phrase = Normalize(row.Phrase);
            var work = Normalize(row.Specialty);
            var service = Normalize(row.ServiceName);
            var score = phrase == clean ? 1000 : 0;

            if (score == 0)
            {
                if (phrase.Contains(clean, StringComparison.Ordinal)) score += 650;
                if (clean.Contains(phrase, StringComparison.Ordinal)) score += 600;
                foreach (var token in tokens)
                {
                    if (token.Length < 3) continue;
                    if (phrase.Contains(token, StringComparison.Ordinal)) score += 180;
                    if (work.Contains(token, StringComparison.Ordinal)) score += 130;
                    if (service.Contains(token, StringComparison.Ordinal)) score += 90;
                }
            }

            return new { Row = row, Score = score };
        })
        .Where(x => x.Score >= 180)
        .OrderByDescending(x => x.Score)
        .ThenBy(x => x.Row.Phrase.Length)
        .Take(Math.Max(limit * 12, 60))
        .ToArray();

        var result = new List<SearchIntentSuggestion>();

        foreach (var hit in hits)
        {
            var row = hit.Row;
            var target = targets.FirstOrDefault(x =>
                    Normalize(x.CategoryName) == Normalize(row.CategoryName) &&
                    Normalize(x.ServiceName) == Normalize(row.ServiceName))
                ?? targets.FirstOrDefault(x =>
                    x.CategorySlug == TaxonomyV3Catalog.ToSlug(row.CategoryName) &&
                    x.ServiceSlug == TaxonomyV3Catalog.ToSlug(row.ServiceName))
                ?? targets.FirstOrDefault(x =>
                    Normalize(x.ServiceName) == Normalize(row.ServiceName));

            if (target is null) continue;

            var label = string.IsNullOrWhiteSpace(row.Specialty) ? row.ServiceName : row.Specialty;
            var id = $"v67:{target.CategorySlug}:{target.ServiceSlug}:{TaxonomyV3Catalog.ToSlug(label)}";

            result.Add(new SearchIntentSuggestion(
                id,
                label,
                [row.Phrase, row.ServiceName, row.Specialty],
                target.CategorySlug,
                target.ServiceSlug,
                InferIntent(row.Phrase),
                hit.Score,
                "v67-dogrudan-ters-indeks"));
        }

        return result
            .GroupBy(x => new { x.CategorySlug, x.ServiceSlug, x.Label })
            .Select(g => g.OrderByDescending(x => x.Score).First())
            .OrderByDescending(x => x.Score)
            .Take(limit)
            .ToArray();
    }
    // NIV-V67-DIRECT-END
public static async Task<SearchIntentSuggestion[]> SuggestAsync(
        AppDbContext dbContext,
        string query,
        int limit,
        CancellationToken cancellationToken)
    {
        var clean = Normalize(query);

        if (clean.Length < 2)
        {
            return [];
        }

        var categories = await dbContext.Categories
            .AsNoTracking()
            .Include(x => x.Services)
            .Where(x => x.IsActive)
            .ToListAsync(cancellationToken);

        var targets = categories
            .SelectMany(category => category.Services
                .Where(service => service.IsActive)
                .Select(service => new ServiceTarget(
                    category.Slug,
                    category.Name,
                    TaxonomyV3Catalog.ToSlug(service.Name),
                    service.Name)))
            .ToArray();
        var directV67 = SearchV67Direct(clean, targets, limit);
        if (directV67.Length > 0) return directV67;

        var candidates = new List<Candidate>(targets.Length * 10);

        foreach (var target in targets)
        {
            AddCandidate(candidates, target.ServiceName, target.ServiceName, target, "service", [], [], "katalog");

            foreach (var phrase in BuildGenericPhrases(target.ServiceName))
            {
                AddCandidate(candidates, target.ServiceName, phrase, target, InferIntent(phrase), [], [], "otomatik-varyasyon");
            }
        }

        foreach (var row in SeedRows)
        {
            var target = ResolveTarget(targets, row.CategoryName, row.ServiceName);

            if (target is null)
            {
                continue;
            }

            var label = string.IsNullOrWhiteSpace(row.Specialty)
                ? row.ServiceName
                : row.Specialty;

            AddCandidate(
                candidates,
                label,
                row.Phrase,
                target,
                InferIntent(row.Phrase),
                [],
                [],
                "master-sozluk");
        }


        // NIV-EXTENDED-INTENTS-USE-START
        // NIV-V66-START
        // TERS MIMARI:
        // Kullanici sorusu -> Is/Ihtiyac -> Hizmet -> Ana Kategori.
        // Performans: 6.159 kaydin tamamini puanlama motoruna vermek yerine
        // once normalize edilmis soru ile ilgili niyet satirlarini daraltir.
        var queryTokensV66 = clean.Split(
            ' ',
            StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);

        var matchedExtendedRowsV66 = ExtendedRows
            .Select(row => new
            {
                Row = row,
                CleanPhrase = Normalize(row.Phrase),
                CleanService = Normalize(row.ServiceName),
                CleanWork = Normalize(row.Specialty)
            })
            .Where(x =>
                x.CleanPhrase == clean ||
                x.CleanPhrase.Contains(clean, StringComparison.Ordinal) ||
                clean.Contains(x.CleanPhrase, StringComparison.Ordinal) ||
                queryTokensV66.Any(token =>
                    token.Length >= 3 &&
                    (x.CleanPhrase.Contains(token, StringComparison.Ordinal) ||
                     x.CleanWork.Contains(token, StringComparison.Ordinal) ||
                     x.CleanService.Contains(token, StringComparison.Ordinal))))
            .Take(160)
            .ToArray();

        foreach (var item in matchedExtendedRowsV66)
        {
            var row = item.Row;
            var target = ResolveTarget(targets, row.CategoryName, row.ServiceName);

            if (target is null)
            {
                // Aktif 251 katalogda isim farklarina karsi normalize fallback.
                target = targets.FirstOrDefault(x =>
                    Normalize(x.ServiceName) == Normalize(row.ServiceName));
            }

            if (target is null)
            {
                continue;
            }

            var label = string.IsNullOrWhiteSpace(row.Specialty)
                ? row.ServiceName
                : row.Specialty;

            AddCandidate(
                candidates,
                label,
                row.Phrase,
                target,
                InferIntent(row.Phrase),
                [],
                [],
                "v66-ters-mimari");
        }
        // NIV-V66-END
// NIV-EXTENDED-INTENTS-USE-END

        foreach (var path in TaxonomyV3Catalog.Paths)
        {
            var target = targets.FirstOrDefault(x =>
                string.Equals(
                    x.CategorySlug,
                    path.LegacyCategorySlug,
                    StringComparison.OrdinalIgnoreCase) &&
                string.Equals(
                    x.ServiceSlug,
                    path.LegacyServiceSlug,
                    StringComparison.OrdinalIgnoreCase));

            if (target is null)
            {
                continue;
            }

            foreach (var term in path.SearchTerms)
            {
                AddCandidate(
                    candidates,
                    path.Specialty,
                    term,
                    target,
                    InferIntent(term),
                    [],
                    [],
                    "taxonomy-v3");
            }
        }

        foreach (var curated in CuratedRows)
        {
            var target = ResolveTarget(targets, null, curated.ServiceName);

            if (target is null)
            {
                continue;
            }

            AddCandidate(
                candidates,
                curated.Label,
                curated.Phrase,
                target,
                curated.Intent,
                curated.Context,
                curated.Negative,
                "baglam-kurali");
        }

        var detectedIntent = InferIntent(clean);
        var queryTokens = Tokens(clean);

        var scored = candidates
            .Select(candidate =>
            {
                var score = ScoreAlias(clean, queryTokens, candidate.Alias);

                foreach (var context in candidate.Context)
                {
                    if (ContainsPhrase(clean, Normalize(context)))
                    {
                        score += 16;
                    }
                }

                foreach (var negative in candidate.Negative)
                {
                    if (ContainsPhrase(clean, Normalize(negative)))
                    {
                        score -= 22;
                    }
                }

                if (detectedIntent != "service" &&
                    candidate.Intent != "service")
                {
                    score += candidate.Intent == detectedIntent ? 12 : -10;
                }

                if (ContainsPhrase(clean, Normalize(candidate.Target.ServiceName)))
                {
                    score += 9;
                }

                score = Math.Clamp(score, 0, 100);

                return new
                {
                    Candidate = candidate,
                    Score = score
                };
            })
            .Where(x => x.Score >= 52)
            .OrderByDescending(x => x.Score)
            .ThenBy(x => x.Candidate.Label)
            .GroupBy(x => new
            {
                x.Candidate.Target.CategorySlug,
                x.Candidate.Target.ServiceSlug,
                x.Candidate.Label,
                x.Candidate.Intent
            })
            .Select(group => group.First())
            .Take(Math.Clamp(limit, 1, 12))
            .Select(x => new SearchIntentSuggestion(
                Id:
                    $"{x.Candidate.Target.CategorySlug}:{x.Candidate.Target.ServiceSlug}:{TaxonomyV3Catalog.ToSlug(x.Candidate.Label)}:{x.Candidate.Intent}",
                Label: x.Candidate.Label,
                Keywords: [x.Candidate.Alias],
                CategorySlug: x.Candidate.Target.CategorySlug,
                ServiceSlug: x.Candidate.Target.ServiceSlug,
                Intent: x.Candidate.Intent,
                Score: x.Score,
                MatchReason: x.Candidate.MatchReason))
            .ToArray();

        return scored;
    }

    public static string Normalize(string? value)
        => TaxonomyV3Catalog.Normalize(value);

    private static void AddCandidate(
        List<Candidate> candidates,
        string label,
        string alias,
        ServiceTarget target,
        string intent,
        string[] context,
        string[] negative,
        string reason)
    {
        if (string.IsNullOrWhiteSpace(alias))
        {
            return;
        }

        candidates.Add(new Candidate(
            label.Trim(),
            Normalize(alias),
            target,
            intent,
            context,
            negative,
            reason));
    }

    private static ServiceTarget? ResolveTarget(
        ServiceTarget[] targets,
        string? categoryName,
        string serviceName)
    {
        var normalizedService = Normalize(serviceName);
        var normalizedCategory = Normalize(categoryName);

        var exact = targets.FirstOrDefault(x =>
            Normalize(x.ServiceName) == normalizedService &&
            (normalizedCategory.Length == 0 ||
             Normalize(x.CategoryName) == normalizedCategory));

        if (exact is not null)
        {
            return exact;
        }

        var serviceMatches = targets
            .Where(x => Normalize(x.ServiceName) == normalizedService)
            .ToArray();

        return serviceMatches.Length == 1
            ? serviceMatches[0]
            : null;
    }

    private static IEnumerable<string> BuildGenericPhrases(string serviceName)
    {
        yield return serviceName;
        yield return $"{serviceName} lazım";
        yield return $"{serviceName} arıyorum";
        yield return $"{serviceName} yaptırmak istiyorum";
        yield return $"{serviceName} hizmeti";
        yield return $"{serviceName} servisi";
        yield return $"{serviceName} tamiri";
        yield return $"{serviceName} kurulumu";
        yield return $"{serviceName} montajı";
        yield return $"{serviceName} fiyatı";
        yield return $"{serviceName} satın almak";
        yield return $"{serviceName} kiralamak";
    }

    private static string InferIntent(string phrase)
    {
        var normalized = Normalize(phrase);

        if (RentalWords.Any(x => ContainsPhrase(normalized, Normalize(x))))
        {
            return "rental";
        }

        if (SaleWords.Any(x => ContainsPhrase(normalized, Normalize(x))))
        {
            return "sale";
        }

        if (RepairWords.Any(x => ContainsPhrase(normalized, Normalize(x))))
        {
            return "repair";
        }

        return "service";
    }

    private static int ScoreAlias(
        string query,
        string[] queryTokens,
        string alias)
    {
        if (query == alias)
        {
            return 100;
        }

        if (query.Length >= 3 && alias.Contains(query, StringComparison.Ordinal))
        {
            return 86;
        }

        if (alias.Length >= 3 && query.Contains(alias, StringComparison.Ordinal))
        {
            return 92;
        }

        var aliasTokens = Tokens(alias);

        if (queryTokens.Length == 0 || aliasTokens.Length == 0)
        {
            return 0;
        }

        var tokenScores = new List<double>();

        foreach (var queryToken in queryTokens)
        {
            var best = aliasTokens
                .Select(aliasToken => TokenSimilarity(queryToken, aliasToken))
                .DefaultIfEmpty(0d)
                .Max();

            tokenScores.Add(best);
        }

        var average = tokenScores.Average();
        var exactHits = queryTokens.Count(qt =>
            aliasTokens.Any(at => at == qt));

        var coverage = (double)exactHits /
            Math.Max(1, Math.Min(queryTokens.Length, aliasTokens.Length));

        return (int)Math.Round(
            Math.Min(
                88,
                average * 68 +
                coverage * 22));
    }

    private static double TokenSimilarity(string left, string right)
    {
        if (left == right)
        {
            return 1d;
        }

        if (left.Length >= 3 &&
            right.Length >= 3 &&
            (left.Contains(right, StringComparison.Ordinal) ||
             right.Contains(left, StringComparison.Ordinal)))
        {
            return 0.9d;
        }

        var distance = LevenshteinDistance(left, right);
        var maxLength = Math.Max(left.Length, right.Length);

        if (maxLength == 0)
        {
            return 0d;
        }

        return Math.Max(
            0d,
            1d - (double)distance / maxLength);
    }

    private static bool ContainsPhrase(string haystack, string needle)
        => needle.Length > 0 &&
           (haystack == needle ||
            haystack.Contains(needle, StringComparison.Ordinal));

    private static string[] Tokens(string value)
        => Normalize(value)
            .Split(
                ' ',
                StringSplitOptions.RemoveEmptyEntries |
                StringSplitOptions.TrimEntries)
            .Where(x => x.Length > 1)
            .ToArray();

    private static int LevenshteinDistance(string left, string right)
    {
        var previous = new int[right.Length + 1];
        var current = new int[right.Length + 1];

        for (var j = 0; j <= right.Length; j++)
        {
            previous[j] = j;
        }

        for (var i = 1; i <= left.Length; i++)
        {
            current[0] = i;

            for (var j = 1; j <= right.Length; j++)
            {
                var cost = left[i - 1] == right[j - 1] ? 0 : 1;

                current[j] = Math.Min(
                    Math.Min(
                        current[j - 1] + 1,
                        previous[j] + 1),
                    previous[j - 1] + cost);
            }

            (previous, current) = (current, previous);
        }

        return previous[right.Length];
    }

    private sealed record ExtendedIntentRow(
        string CategoryName,
        string ServiceName,
        string WorkName,
        string Phrase)
    {
        public string Specialty => WorkName;
    }
}
